def two_sum_brute(nums, target):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [i, j]
    return []


def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        need = target - num
        if need in seen:
            return [seen[need], i]
        seen[num] = i
    return []

def longest_substring_bruteforce(s: str) -> int:
    """Return length of longest substring without repeating characters using O(n^2) check."""
    n = len(s)
    best = 0
    for i in range(n):
        seen = set()
        for j in range(i, n):
            if s[j] in seen:
                break
            seen.add(s[j])
            best = max(best, j - i + 1)
    return best

def longest_substring_window(s: str) -> int:
    """Return length of longest substring without repeating characters using sliding window."""
    last = {}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        best = max(best, right - left + 1)
    return best

def binary_search(a: list[int], target: int) -> int:
    """Closed interval [lo, hi]: return an index of target in sorted a, or -1."""
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def search_first(a: list[int], target: int) -> int:
    """Half-open interval [lo, hi): return the FIRST index of target in sorted a, or -1."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(a) and a[lo] == target else -1

"""Number of Islands: count groups of "1" cells joined up, down, left or right.

One outer scan finds each new island; a flood fill (BFS, stack DFS or recursive DFS)
marks the whole island as seen so it is never counted twice.
"""
from collections import deque


def neighbors(grid, r, c):
    for nr, nc in (r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1):
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == "1":
                yield nr, nc


def bfs(grid, r, c, seen):
    seen.add((r, c))
    queue = deque([(r, c)])
    while queue:
        cr, cc = queue.popleft()          # oldest cell first: rings
        for nb in neighbors(grid, cr, cc):
            if nb not in seen:
                seen.add(nb)              # mark when it joins the queue
                queue.append(nb)


def dfs_stack(grid, r, c, seen):
    seen.add((r, c))
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()              # newest cell first: dives deep
        for nb in neighbors(grid, cr, cc):
            if nb not in seen:
                seen.add(nb)
                stack.append(nb)


def dfs_recursive(grid, r, c, seen):
    seen.add((r, c))
    for nb in neighbors(grid, r, c):
        if nb not in seen:
            dfs_recursive(grid, *nb, seen)


def count_islands(grid, flood=bfs):
    if not grid or not grid[0]:
        return 0
    seen, islands = set(), 0
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == "1" and (r, c) not in seen:
                islands += 1
                flood(grid, r, c, seen)
    return islands

