from contextlib import contextmanager

@contextmanager
def shopping():
    print("take list")
    try:
        yield ["milk", "bread"]
    finally:
        print("put list away")

try:
    with shopping():
        raise ValueError("bad milk")
except ValueError as error:
    print("caught:", error)

from contextlib import contextmanager

settings = {"lang": "en"}

@contextmanager
def language(new):
    old = settings["lang"]
    settings["lang"] = new
    try:
        yield
    finally:
        settings["lang"] = old

with language("ms"):
    print(settings["lang"])
print(settings["lang"])
